- 2), min(len(lines), row_idx + 10)):\n                    raw = norm(str(lines[k].get(\"text\", \"\")))\n                    if raw:\n                        snippet_lines.append(raw)\n                if snippet_lines:\n                    return add_line_span(\"\\n\".join(snippet_lines), lines[row_idx])\n\n        for para in paragraphs:\n            raw_text = str(para.get(\"text\", \"\"))\n            lowered = norm(raw_text).lower()\n\n            if \"summary of fiscal operations\" in lowered and \"surplus\" in lowered and \"deficit\" in lowered:\n                start_match = re.search(r\"fiscal\\s+\\d{4}\\s+to\\s+date\", raw_text, re.IGNORECASE)\n                label_match = re.search(\n                    r\"surplus\\s*(?:\\(\\+\\))?\\s*or\\s*deficit\",\n                    raw_text,\n                    re.IGNORECASE,\n                )\n                means_match = re.search(r\"means\\s+of\\s+f\\s*i\\s*n\", raw_text, re.IGNORECASE)\n                start = start_match.start() if start_match else max(0, (label_match.start() - 250) if label_match else 0)\n                end = means_match.start() if means_match and means_match.start() > start else min(len(raw_text), start + 1800)\n                snippet = raw_text[start:end]\n                if label_match and snippet:\n                    return add_paragraph_span(snippet, para)\n\n            if \"total on\" in lowered and \"budget results\" in lowered and \"surplus\" in lowered and \"deficit\" in lowered:\n                label_match = re.search(\n                    r\"total\\s+surplus.*?deficit.*?(?:(?<!\\w)-?\\d[\\d,]*\\s*){1,4}\",\n                    raw_text,\n                    re.IGNORECASE | re.DOTALL,\n                )\n                if label_match:\n                    start = max(0, label_match.start() - 120)\n                    end = min(len(raw_text), label_match.end() + 120)\n                    return add_paragraph_span(raw_text[start:end], para)\n\n        return []\n    except E